  const dips = ["αι","ει","οι","ου","αυ","ευ","ηυ","υι"];
  return dips.some(d => v.includes(d));
}

function lastVowelIndexNFD(word){
  const d = nfd(word);
  // Find last base vowel (not combining)
  for (let i=d.length-1;i>=0;i--){
    const ch = d[i];
    if (/[\u0300-\u036f]/.test(ch)) continue;
    if (greekVowel(ch)) return i;
  }
  return -1;
}

function penultVowelIndexNFD(word){
  // Find penult vowel (base) index in NFD by scanning base letters and counting vowel groups.
  const base = stripDiacriticsKeepLetters(word);
  const syl = countSyllables(base);
  if (syl < 2) return lastVowelIndexNFD(word);

  // Determine which vowel group is penult in base string.
  const b = base;
  const groups = [];
  let inV = false;
  let start = -1;
  for (let i=0;i<b.length;i++){
    const v = greekVowel(b[i]);
    if (v && !inV){ inV = true; start = i; }
    if (!v && inV){ inV = false; groups.push({start, end:i-1}); }
  }
  if (inV) groups.push({start, end:b.length-1});
  const penGroup = groups[Math.max(0, groups.length-2)];

  // Map base index to NFD index by walking NFD and counting base letters.
  const d = nfd(word);
  let basePos = -1;
  for (let i=0;i<d.length;i++){
    const ch = d[i];
    if (/[\u0300-\u036f]/.test(ch)) continue;
    basePos++;
    if (basePos === penGroup.start){
      // return index of first vowel letter in that group (start)
      return i;
    }
  }
  return lastVowelIndexNFD(word);
}

function addAcuteOnPenult(word){
  const w = stripAccentOnly(word);
  const d = nfd(w);
  const idx = penultVowelIndexNFD(w);
  if (idx < 0) return word;
  // Insert acute after the base vowel at idx, but after any breathing/diaeresis already attached to that vowel.
  // In NFD, combining marks follow the base. We'll insert after existing combining marks that immediately follow.
  let j = idx+1;
  while (j < d.length && /[\u0300-\u036f]/.test(d[j])) j++;
  d.splice(j, 0, COMBINING.acute);
  return nfc(d.join(""));
}

function addGraveOnPenult(word){
  const w = stripAccentOnly(word);
  const d = nfd(w);
  const idx = penultVowelIndexNFD(w);
  if (idx < 0) return word;
  let j = idx+1;
  while (j < d.length && /[\u0300-\u036f]/.test(d[j])) j++;
  d.splice(j, 0, COMBINING.grave);
  return nfc(d.join(""));
}

function normalizeInput(s){
  return (s||"").trim().replace(/\s+/g," ");
}

function guessKind(word){
  const base = stripDiacriticsKeepLetters(word).toLowerCase();
  // Very rough: ethnics in -γέτης/-γέται etc.
  if (base.endsWith("γετης") || base.endsWith("γεται")) return "ethnic";
  // Agentive often from verbs: -ητης after verbal stem; but we can't know. Use common agentive list endings.
  return "verbal";
}

function suggest(word, kindChoice, penChoice){
  const raw = normalizeInput(word);
  if (!raw) return {ok:false, msg:"Type a Greek word first."};

  const base = stripDiacriticsKeepLetters(raw);
  const endsT = /της$/i.test(base);
  if (!endsT) {
    return {ok:false, msg:"This toy is for words ending in -της. Try e.g. μαθητής, κομήτης, Μασσαγέτης."};
  }

  const syll = countSyllables(base);
  const penVG = penultVowelGroup(base);

  let penLong;
  if (penChoice === "auto") penLong = isLongByNature(penVG);
  else penLong = (penChoice === "long");

  let kind;
  if (kindChoice === "auto") {
    const g = guessKind(base);
    kind = (g === "ethnic") ? "nonverbal" : "verbal";
  } else kind = kindChoice;

  // Apply Herodian-inspired heuristic:
  // verbal, >2 syllables, long penult => acute on penult.
  // nonverbal, long penult => grave (barytone) on penult.
  // otherwise: default to acute on penult (common modern expectation), but warn.
  let form, tag, expl;
  if (kind === "verbal" && syll > 2 && penLong){
    form = addAcuteOnPenult(base);
    tag = {cls:"good", text:"acute (ὀξύνεται)"};
    expl = "Heuristic: verbal -της, >2 syllables, long penult → acute.";
  } else if (kind === "nonverbal" && penLong){
    form = addGraveOnPenult(base);
    tag = {cls:"warn", text:"grave/barytone (βαρύνεται)"};
    expl = "Heuristic: non‑verbal -της with long penult → barytone (shown here with grave).";
  } else {
    form = addAcuteOnPenult(base);
    tag = {cls:"warn", text:"uncertain"};
    expl = "Outside the highlighted condition; this is a best‑guess accent placement.";
  }

  const meta = {
    syllables: syll,
    penultGroup: penVG || "(unknown)",
    penultLong: penLong ? "long" : "short/unknown",
    kind
  };

  return {ok:true, raw, base, form, tag, expl, meta};
}

function renderSuggestion(res){
  const out = $("#out");
  if (!res.ok){
    out.innerHTML = `<div class="meta"><span class="k bad">No result</span><div>${escapeHtml(res.msg)}</div></div>`;
    return;
  }
  out.innerHTML = `
    <div class="big">${escapeHtml(res.form)}</div>
    <div class="meta">
      <div><span class="k ${res.tag.cls}">${escapeHtml(res.tag.text)}</span> <span class="k">input: ${escapeHtml(res.base)}</span></div>
      <div>${escapeHtml(res.expl)}</div>
      <div>syllables: <b>${res.meta.syllables}</b> · penult vowel-group: <b>${escapeHtml(res.meta.penultGroup)}</b> · penult: <b>${res.meta.penultLong}</b> · type: <b>${escapeHtml(res.meta.kind)}</b></div>
      <div class="tiny">Tip: try toggling “type” and “penult length” to see how the rule changes the accent.</div>
    </div>
  `;
}

function escapeHtml(s){
  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function getRadio(name){
  const el = $(`input[name="${name}"]:checked`);
  return el ? el.value : "auto";
}

// --- Mini sorting game ---
const WORDS = [
  {w:"Μασσαγέτης", bin:"ethnic"},
  {w:"Θυσσαγέτης", bin:"ethnic"},
  {w:"Τορέτης", bin:"ethnic"},
  {w:"Μυργέτης", bin:"ethnic"},
  {w:"Μακέτης", bin:"ethnic"},
  {w:"μαθητής", bin:"agent"},
  {w:"ποιητής", bin:"agent"},
  {w:"πειρατής", bin:"agent"},
  {w:"τοξότης", bin:"agent"},
  {w:"δεσπότης", bin:"other"},
  {w:"κομήτης", bin:"other"},
  {w:"εὑρετής", bin:"agent"}
];

function makeToken(text){
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'token';
  b.textContent = text;
  b.dataset.home = 'bank';
  b.addEventListener('click', () => cycleToken(b));
  return b;
}

function cycleToken(tok){
  const order = ['bank','binEth','binAg','binOt'];
  const cur = tok.parentElement?.id || 'bank';
  const idx = order.indexOf(cur);
  const next = order[(idx+1) % order.length];
  $("#"+next).appendChild(tok);
}

function resetGame(){
  const bank = $("#bank");
  bank.innerHTML = "";
  $("#binEth").innerHTML = "";
  $("#binAg").innerHTML = "";
  $("#binOt").innerHTML = "";
  const shuffled = WORDS.slice().sort(()=>Math.random()-0.5);
  for (const it of shuffled){
    const t = makeToken(it.w);
    t.dataset.answer = it.bin;
    bank.appendChild(t);
  }
  $("#score").textContent = "Click a token to move it: bank → ethnic → agent → other → bank.";
}

function checkGame(){
  let total = 0, correct = 0;
  for (const tok of $$('.token')){
    total++;
    const parentId = tok.parentElement?.id;
    const placed = parentId === 'binEth' ? 'ethnic' : parentId === 'binAg' ? 'agent' : parentId === 'binOt' ? 'other' : 'bank';
    if (placed !== 'bank' && placed === tok.dataset.answer) correct++;
  }
  const placedCount = total - $$('#bank .token').length;
  const msg = `Placed: ${placedCount}/${total}. Correct (among placed): ${correct}/${Math.max(1, placedCount)}.`;
  $("#score").textContent = msg;
}

// --- Wire up UI ---
function runSuggest(){
  const word = $("#w").value;
  const kind = getRadio('kind');
  const pen = getRadio('pen');
  const res = suggest(word, kind, pen);
  renderSuggestion(res);
}

$("#go").addEventListener('click', runSuggest);
$("#w").addEventListener('keydown', (e)=>{ if(e.key==='Enter') runSuggest(); });

$("#rand").addEventListener('click', ()=>{
  const samples = [
    "μαθητης",
    "ποιητης",
    "κομητης",
    "Μασσαγετης",
    "Θυσσαγετης",
    "κυβερνητης",
    "αθλητης",
    "δεσποτης"
  ];
  $("#w").value = samples[Math.floor(Math.random()*samples.length)];
  runSuggest();
});

$("#reset").addEventListener('click', resetGame);
$("#check").addEventListener('click', checkGame);

// initial
resetGame();
renderSuggestion({ok:false, msg:"Type a -της word above, then click “Suggest accent”."});

