const word=document.querySelector('#word'), context=document.querySelector('#context'), answer=document.querySelector('#answer');
const plain=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const examples={αθηναιος:'Ἀθηναῖος',ειρηναιος:'Εἰρηναῖος',αρουραιος:'ἀρουραῖος',αγοραιος:'ἀγοραῖος',δωδωναιος:'Δωδωναῖος'};
function show(form,note){answer.replaceChildren();const title=document.createElement('strong');title.textContent=form;const p=document.createElement('p');p.textContent=note;answer.append(title,p);}
function run(){const key=plain(word.value);if(!key){show('Enter a Greek word','Choose a passage example to begin.');return;}
if(key==='ερυσιχαιος'){if(context.value==='ethnic')show('Ἐρυσιχαῖος','Ethnic reading: circumflex on the penult. Join it to Θεσσαλὸς γένος (Thessalian by race).');else show('ἐρυσίχαιος','Pastoral compound: acute on the antepenult (proparoxytone). Join it to οὐδὲ ποιμήν (nor shepherd): cowherd or goatherd; shepherd is added in apposition.');}
else if(examples[key])show(examples[key],'Passage example: circumflex on the penult. The stated rule concerns -αιος words of more than three syllables, with qualifications for distinctions and compounds.');
else show('Outside this example set','No accent prediction is made. Try Ἀθηναῖος or Ἐρυσιχαῖος.');}
document.querySelector('#read').addEventListener('click',run);word.addEventListener('keydown',e=>{if(e.key==='Enter')run();});context.addEventListener('change',run);
for(const text of ['Ερυσιχαιος',...Object.values(examples)]){const btn=document.createElement('button');btn.textContent=text;btn.addEventListener('click',()=>{word.value=text;run();});document.querySelector('#examples').append(btn);}
document.querySelector('#reset').addEventListener('click',()=>{word.value='';context.value='ethnic';run();});run();

