  --bad:#fb7185;
  --warn:#fbbf24;
}
*{box-sizing:border-box}
body{margin:0;background:radial-gradient(1200px 700px at 20% 0%, #1b1f3a 0%, var(--bg) 55%);color:var(--ink);font:15px/1.35 system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif}
.wrap{max-width:980px;margin:24px auto;padding:0 16px 28px}
.head{display:flex;gap:14px;align-items:flex-end;justify-content:space-between;margin-bottom:14px}
h1{font-size:22px;margin:0 0 6px}
.sub{margin:0;color:var(--muted)}
.card{background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));border:1px solid var(--line);border-radius:14px;padding:14px 14px 12px;margin:12px 0;box-shadow:0 10px 30px rgba(0,0,0,.25)}
.card h2{font-size:16px;margin:0 0 10px;color:#f3f4ff}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.lab{min-width:170px;color:var(--muted)}
.inp{flex:1;min-width:260px;padding:10px 12px;border-radius:10px;border:1px solid var(--line);background:#0c0f1c;color:var(--ink);outline:none}
