.btn{padding:9px 12px;border-radius:10px;border:1px solid rgba(125,211,252,.35);background:rgba(125,211,252,.12);color:var(--ink);cursor:pointer}
.btn:hover{background:rgba(125,211,252,.18)}
.btn:active{transform:translateY(1px)}
.btn.ghost{border-color:rgba(167,139,250,.35);background:rgba(167,139,250,.10)}
.btn.ghost:hover{background:rgba(167,139,250,.16)}
.opts{margin-top:10px;align-items:stretch}
.opt{flex:1;min-width:280px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18)}
.optTitle{padding:10px 10px 0;color:#dfe3ff;font-weight:600}
.optBody{padding:8px 10px 10px;display:grid;gap:6px;color:var(--muted)}
.optBody label{display:flex;gap:8px;align-items:flex-start}
.out{margin-top:12px;border:1px dashed rgba(238,240,255,.25);border-radius:12px;padding:10px 12px;background:rgba(0,0,0,.18)}
.out .big{font-size:20px;letter-spacing:.2px}
.out .meta{margin-top:6px;color:var(--muted);display:grid;gap:4px}
.k{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:#e9ecff;font-size:12px}
.k.good{border-color:rgba(52,211,153,.35);background:rgba(52,211,153,.10)}
