.opt{flex:1;min-width:280px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18)}
.optTitle{padding:10px 10px 0;color:#dfe3ff;font-weight:600}
.optBody{padding:8px 10px 10px;display:grid;gap:6px;color:var(--muted)}
.optBody label{display:flex;gap:8px;align-items:flex-start}
.out{margin-top:12px;border:1px dashed rgba(238,240,255,.25);border-radius:12px;padding:10px 12px;background:rgba(0,0,0,.18)}
.out .big{font-size:20px;letter-spacing:.2px}
.out .meta{margin-top:6px;color:var(--muted);display:grid;gap:4px}
.k{display:inline-block;padding:2px 8px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.04);color:#e9ecff;font-size:12px}
.k.good{border-color:rgba(52,211,153,.35);background:rgba(52,211,153,.10)}
.k.bad{border-color:rgba(251,113,133,.35);background:rgba(251,113,133,.10)}
.k.warn{border-color:rgba(251,191,36,.35);background:rgba(251,191,36,.10)}
.notes{margin-top:10px;color:var(--muted)}
.notes summary{cursor:pointer}
.notesBody{padding-top:8px}
.game{display:grid;gap:10px}
.bank{display:flex;flex-wrap:wrap;gap:8px;padding:10px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18);min-height:52px}
.token{user-select:none;cursor:pointer;padding:6px 10px;border-radius:999px;border:1px solid rgba(238,240,255,.18);background:rgba(255,255,255,.05);color:var(--ink);font-family:ui-serif, "Noto Serif", "Times New Roman", serif}
.token:hover{border-color:rgba(125,211,252,.55)}
.bins{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.bin{border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.12);min-height:110px;display:flex;flex-direction:column}
.binHead{padding:10px 10px 0;font-weight:700;color:#e9ecff}
.binBody{padding:10px;display:flex;flex-wrap:wrap;gap:8px;min-height:70px}
.score{color:var(--muted)}
.foot{margin-top:10px;color:var(--muted)}
.tiny{font-size:12px}
@media (max-width:860px){.bins{grid-template-columns:1fr}}

